#ifdef HAVE_CONFIG_H
#include "config.h"
#endif
#define COIN_RENDER_SHADOW_MULTITEXTURE_WINDOW_FIXTURE_ONLY
#include "CoinRenderShadowMultitextureWindowTest.cpp"
#include "CoinRenderShadowSpatialFixture.h"
namespace {
bool spatialWindowCoverage(WindowPair&pair){if(windowSamples==1)return true;SpatialScene s(2,128,false,1.f,1);s.paint(false);s.replace(7);for(int x=0;x<3;++x){auto p=s.positions->point[6+x];p[1]=1.31f+.22f*x;s.positions->point.set1Value(6+x,p);}Frame f;if(!pair.frame(s,f,"spatial effective MSAA coverage",true))return false;auto expected=s.sampled(7);bool ok=true;for(const auto*rgba:{&f.rgba,&pair.lastReadback,&pair.lastShown}){size_t bad=0,partial=0,odd=0;for(size_t p=0;p+3<rgba->size();p+=4){int match=-1;for(unsigned k=0;k<=windowSamples;++k){bool same=true;for(unsigned c=0;c<3;++c)same &=std::abs(double((*rgba)[p+c])*windowSamples-expected[c]*k)<=3*windowSamples;if(same){match=int(k);break;}}bad+=match<0;partial+=match>0&&match<int(windowSamples);odd+=windowSamples==4&&(match==1||match==3);}std::cout<<"spatial_window_effective samples="<<windowSamples<<" bad="<<bad<<" partial="<<partial<<" odd_quarters="<<odd<<'\n';ok &=check(bad==0&&partial>0&&(windowSamples!=4||odd>0),"spatial actual MSAA resolved k/N including odd quarter levels");}return ok;}
bool spatialWindow(const CoinRenderCapabilities&caps,bool rtt,CoinRenderSceneTextureMode route){WindowPair pair(caps,0,nullptr,COIN_RENDER_TRANSPARENCY_COIN,route);if(!pair.ready)return false;bool ok=spatialWindowCoverage(pair);
  if(rtt){for(int kind:{0,1}){SpatialRttScene graph(kind);Frame white,colored,back;ok &=pair.frame(graph.consumer,white,"spatial RTT window white",true,false,1);graph.colored();const auto produced=graph.produced();if(pair.frame(graph.consumer,colored,"spatial RTT window colored",true,false,1))ok &=spatialComposition(graph.consumer,white,colored,SoTexture2::MODULATE,pair.extent,&produced);else ok=false;auto original=graph.producerScene.uvw[7]->point[0];graph.producerScene.raw(7,SbVec3f(original[0],original[1],std::numeric_limits<float>::quiet_NaN()));ok &=pair.refuse(graph.consumer,"spatial RTT window producer NaN R",true);graph.producerScene.raw(7,original);ok &=pair.frame(graph.consumer,back,"spatial RTT producer R recovery",true,false,1)&&exact(colored,back);auto originalMatrix=graph.producerScene.matrices[7]->matrix.getValue();auto invalidMatrix=originalMatrix;invalidMatrix[3][3]=std::numeric_limits<float>::quiet_NaN();graph.producerScene.matrices[7]->matrix=invalidMatrix;ok &=pair.refuse(graph.consumer,"spatial RTT window producer nonfinite Q",true);graph.producerScene.matrices[7]->matrix=originalMatrix;ok &=pair.frame(graph.consumer,back,"spatial RTT producer Q recovery",true,false,1)&&exact(colored,back);graph.white();ok &=pair.frame(graph.consumer,back,"spatial RTT window restored",true,false,1)&&exact(white,back);}return ok;}
  SpatialScene scene(2,255);Frame white,colored,back;
  for(int size:{128,65,160,128}){if(size!=pair.extent)ok &=pair.resize(size);scene.paint(true);if(!pair.frame(scene,white,"spatial window white",true)){ok=false;continue;}scene.paint(false);if(pair.frame(scene,colored,"spatial window colored",true))ok &=spatialComposition(scene,white,colored,SoTexture2::MODULATE,unsigned(size));else ok=false;scene.paint(true);ok &=pair.frame(scene,back,"spatial window restored",true);if(size==128)ok &=exact(white,back);}
  scene.paint(false);ok &=pair.frame(scene,colored,"spatial window invalid control",true);auto old=scene.uvw[7]->point[0];scene.raw(7,SbVec3f(old[0],old[1],std::numeric_limits<float>::quiet_NaN()));ok &=pair.refuse(scene,"spatial window NaN R",true);scene.raw(7,old);ok &=pair.frame(scene,back,"spatial window invalid recovery",true)&&exact(colored,back);return ok;
}
}
int main(int argc,char**argv){configureSamplingTest(argc,argv);bool rtt=false;CoinRenderSceneTextureMode route=COIN_RENDER_SCENE_TEXTURE_STAGED;for(int i=1;i<argc;++i){std::string a=argv[i];if(a=="--portable-sampling")continue;if(a=="--samples"&&i+1<argc){windowSamples=unsigned(std::strtoul(argv[++i],nullptr,10));continue;}if(a=="--rtt"){rtt=true;continue;}if(a=="--direct"){route=COIN_RENDER_SCENE_TEXTURE_DIRECT;continue;}if(a=="--staged")continue;return 2;}if(windowSamples!=1&&windowSamples!=2&&windowSamples!=4)return 2;if(!XInitThreads())return 1;SoDB::init();CoinRenderAction::initClass();auto caps=msaa_shadow_test::capabilities(COIN_RENDER_EXPERIMENTAL_XLIB_WINDOW);if(!caps.gpu_available)return 77;return spatialWindow(caps,rtt,route)?0:1;}
